from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.procedure import environment_preparator
from taf.ul.sc.perf.procedure import environment_collector
from taf.ul.sc.perf.procedure import site_verification
from taf.ul.sc.perf.procedure import test_monitors
from taf.ul.sc.perf.procedure import scenario_runner
from taf.ul.sc.perf.procedure import actions_during_scenario
from taf.ul.sc.perf.procedure.logs_collector import LogsCollector
from taf.ul.sc.perf.procedure import db_markers
from taf.ul.sc.perf.procedure import post_actions
from taf.ul.sc.perf.util.logger import (log_debug_function_info, log_function_info_to_console,
                                        log_info_to_console, log_info_with_status_to_console)


# @log_function_info_to_console(msg="Initial Actions", banner=True)
# @log_debug_function_info()
def initial_actions():
    pass


@log_debug_function_info()
def prepare_environment():
    msg = "Preparing environment: CORE/UE/BTS"
    if tc.is_feature_enabled("bts_preparation") or tc.is_feature_enabled("ue_preparation"):
        log_info_to_console(msg=msg, banner=True)
    else:
        log_info_with_status_to_console(msg=msg, status='SKIPPED')

    if tc.is_feature_enabled("use_configurator"):
        environment_preparator.prepare_with_configurator()
    else:
        environment_preparator.prepare_core()
        environment_preparator.prepare_ue()
        environment_preparator.prepare_bts()


@log_function_info_to_console(msg="Collecting environment info", banner=True)
@log_debug_function_info()
def collect_environment_info():
    environment_collector.collect_basic_test_case_info()
    environment_collector.set_teb_default_values()
    environment_collector.collect_bts_version()
    environment_collector.collect_ue_version()
    environment_collector.collect_core_version()
    environment_collector.collect_bts_hw_info()
    environment_collector.collect_bts_cells_info()
    environment_collector.collect_rrh_info()


@log_function_info_to_console(msg="Verify if Test Line is ready to run test", banner=True)
@log_debug_function_info()
def verify_if_test_line_is_ready_to_run_test():
    site_verification.wait_for_all_sites_onair()
    site_verification.perform_additional_actions_before_start_scenario()
    site_verification.verify_if_sample_scenario_can_be_run()  # not implemented yet


@log_function_info_to_console(msg="Starting test monitors", banner=True)
@log_debug_function_info()
def start_test_monitors():
    test_monitors.clear_sgw_and_pgw_stats()
    test_monitors.show_sgw_and_pgw_stats()
    test_monitors.start_benchmark_stats_collecting()
    test_monitors.start_dsp_stats_collecting()
    test_monitors.start_fake_paging()
    test_monitors.start_test_recovery_observers()
    test_monitors.start_additional_cmds()
    test_monitors.clear_bts_stats()


@log_function_info_to_console(msg="Starting test scenario", banner=True)
@log_debug_function_info()
def start_scenario():
    try:
        environment_collector.add_uptime_before_test_for_all_btss()
        db_markers.add_start_test_timestamp()
    except AttributeError as e:
        log_info_to_console("Uptime before test for all BTSs not added. Reason: {}".format(e))
        MolerTest.warning(msg="Uptime before test for all BTSs not added. Reason: {}".format(e))
    MolerTest.info(msg="Starting scenario...")
    scenario_runner.start_scenario()


@log_debug_function_info()
def schedule_action_performing_during_scenario():
    if tc.is_feature_enabled("collect_tti_traces"):
        actions_during_scenario.collect_tti_traces()


@log_function_info_to_console(msg="Waiting till scenario finish ...", banner=True)
@log_debug_function_info()
def wait_untill_scenario_finish():
    db_markers.add_scenario_duration()
    scenario_runner.sleep_for_the_rest_of_the_time()


@log_function_info_to_console(msg="Stopping scenario", banner=True)
@log_debug_function_info()
def stop_scenario():
    db_markers.add_stop_test_timestamp()
    db_markers.add_measured_scenario_duration()
    scenario_runner.stop_scenario()
    environment_collector.add_uptime_after_test_for_all_btss()
    scenario_runner.wait_for_last_bts_stats()


@log_function_info_to_console(msg="Stopping test monitors", banner=True)
@log_debug_function_info()
def stop_test_monitors():
    test_monitors.stop_additional_cmds()
    test_monitors.show_sgw_and_pgw_stats()
    test_monitors.stop_test_recovery_observers()
    test_monitors.save_bts_stats()
    test_monitors.stop_benchmark_stats_collecting()
    test_monitors.stop_dsp_stats_collecting()
    test_monitors.stop_fake_paging()


@log_function_info_to_console(msg="Collecting logs after test", banner=True)
@log_debug_function_info()
def collecting_logs():
    collector = LogsCollector()
    try:
        collector.collect_bts_logs()
    except Exception as e:
        MolerTest.warning(msg="BTS logs not collected. Reason: {}".format(e))
    try:
        collector.collect_ue_logs()
    except Exception as e:
        MolerTest.warning(msg="CUS logs not collected. Reason: {}".format(e))
    try:
        collector.collect_core_simulator_logs()
    except Exception as e:
        MolerTest.warning(msg="Core simulator logs not collected. Reason: {}".format(e))


@log_function_info_to_console(msg="Prepare & Run post actions", banner=True)
@log_debug_function_info()
def run_post_actions():
    post_actions.make_bin_directory()
    post_actions.save_run_params_to_json_file()
    post_actions.save_execution_stats_to_json_file()
    post_actions.save_moler_configuration_to_json_file()
    if tc.is_feature_enabled("post_process"):
        post_actions.run_post_process()
